"""Install destination alternate comparisons on the release 200 Pages build."""
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys
import zipfile

dist = Path('dist')
manifest_path = dist / 'data/render-release.json'
manifest = json.loads(manifest_path.read_text())
assert manifest['version'] == 200
brief_path = dist / 'src/route-brief184.js'
baseline = re.sub(r'(?<=\.js)\?v=[0-9.]+', '', brief_path.read_text())
assert hashlib.sha256(baseline.encode()).hexdigest() == 'ce6e463835a2e77fd2b0b52762ba21fa9c63a3e1e1593e8a07706b1087019f97'
app_path = dist / 'src/app.js'
app = app_path.read_text()
call = 'showAirportBrief181(openModal,departure,arrival,{plan:selectedRoute136,spec,weather})'
assert app.count(call) == 1
app_path.write_text(app.replace(call, call.replace('spec,weather', 'spec,weather,airports')))
brief_path.write_text('import {distanceKm,bearing} from \'./physics.js\';\nimport {altitudeText136,speedText136,validFix136} from \'./procedure-reference136.js\';\nimport {weatherEnvironment,localClock} from \'./weather-settings125.js\';\nconst esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst num=(v,n=0)=>Number.isFinite(v)?v.toLocaleString(\'en-US\',{maximumFractionDigits:n}):\'Not published\';\nconst trackText = degrees => String(Math.round(degrees) % 360).padStart(3,\'0\') + \'°T\';\nconst link=url=>typeof url===\'string\'&&/^https?:\\/\\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noreferrer">Source chart / data ↗</a>`:\'\';\nfunction runwayWindTable(airport, weather) {\n const rows = [];\n for (const runway of airport.runways || []) {\n  if (![runway.a, runway.b].every(end => Array.isArray(end) && end.length === 2 && end.every(Number.isFinite))) continue;\n  const [a,b] = [runway.a, runway.b].map(([lon,lat]) => ({lon,lat}));\n  if (distanceKm(a,b) < 0.001) continue;\n  const names = String(runway.name || \'\').split(\'/\');\n  for (const [index, track] of [bearing(a,b), bearing(b,a)].entries()) {\n   const delta = (weather.windFromDeg - track) * Math.PI / 180;\n   const head = Math.round(weather.windSpeedKt * Math.cos(delta));\n   const cross = Math.round(weather.windSpeedKt * Math.sin(delta));\n   const longitudinal = head ? Math.abs(head) + \' kt \' + (head > 0 ? \'headwind\' : \'tailwind\') : \'0 kt\';\n   const lateral = cross ? Math.abs(cross) + \' kt from \' + (cross > 0 ? \'right\' : \'left\') : \'0 kt\';\n   rows.push(`<tr><th scope="row">${esc(names[index] || \'—\')}</th><td>${trackText(track)}</td><td>${longitudinal}</td><td>${lateral}</td></tr>`);\n  }\n }\n return `<article><h4>${esc(airport.icao)} · ${esc(airport.name)}</h4><div class="brief-table184"><table><thead><tr><th>Runway</th><th>Heading</th><th>Along runway</th><th>Crosswind</th></tr></thead><tbody>${rows.join(\'\')}</tbody></table></div></article>`;\n}\n\nfunction alternateAirports(arrival, airports) {\n const nearby = [];\n for (const airport of airports) {\n  if (airport.icao === arrival.icao || !Number.isFinite(airport.lat) || !Number.isFinite(airport.lon)) continue;\n  const longest = (airport.runways || []).reduce((best, runway) =>\n   Number.isFinite(runway.length) && runway.length > (best?.length || 0) ? runway : best, null);\n  if (longest) nearby.push({airport, longest, nm:distanceKm(arrival,airport)/1.852});\n }\n nearby.sort((a,b) => a.nm-b.nm || a.airport.icao.localeCompare(b.airport.icao));\n if (!nearby.length) return \'\';\n const rows = nearby.slice(0,4).map(({airport,longest,nm}) => {\n  const track = trackText(bearing(arrival,airport));\n  return `<tr><th scope="row">${esc(airport.icao)} · ${esc(airport.name)}</th><td>${num(nm,1)} NM</td><td>${track}</td><td>${esc(longest.name)} · ${num(longest.length)} M</td></tr>`;\n });\n return `<details><summary>Nearby alternate airports</summary><p>Distance and bearing from ${esc(arrival.icao)}. Sorted by distance. Check runway suitability for your aircraft.</p><div class="brief-table184"><table><thead><tr><th>Airport</th><th>Distance</th><th>Bearing</th><th>Longest runway</th></tr></thead><tbody>${rows.join(\'\')}</tbody></table></div></details>`;\n}\n\nfunction airwayLimits(leg) {\n const min = leg.minFL, max = leg.maxFL;\n if (Number.isFinite(min) && Number.isFinite(max)) return `AIRWAY FL ${min}–${max}`;\n if (Number.isFinite(min)) return `AT OR ABOVE FL ${min}`;\n if (Number.isFinite(max)) return `AT OR BELOW FL ${max}`;\n return \'Not published\';\n}\n\nexport function routeBrief184(departure,arrival,{plan,spec,weather,airports=[]}={}){\n const w=weatherEnvironment(weather),points=plan?.status===\'routed\'?plan.points||[]:[],legs=plan?.legs||[],procedure=plan?.arrival142||plan?.cloudBreak145,sourceRows=procedure?.sourceLegs148||procedure?.legs||[];\n let cumulative=0,previous=null;const rows=[];\n for(let i=0;i<points.length;i++){\n  if(i)cumulative+=distanceKm(points[i-1],points[i]);\n  const p=points[i];if(p.geometrySample145)continue;\n  const e=legs[Math.max(0,i-1)]||{},distance=previous?cumulative-previous.distance:0,track=previous?bearing(previous.point,p):null;\n  rows.push(`<tr><td>${rows.length+1}</td><th scope="row">${esc(p.name)}</th><td>${esc(e.airway||e.kind||\'Departure\')}</td><td>${num(distance/1.852,1)}</td><td>${track===null?\'—\':trackText(track)}</td><td>${num(cumulative/1.852,1)}</td><td>${p.kind===\'procedure\'?esc(altitudeText136(p)):e.kind===\'airway\'?airwayLimits(e):\'Not published\'}</td><td>${esc(speedText136(p))}</td><td>${num(p.lat,5)}, ${num(p.lon,5)}</td></tr>`);\n  previous={point:p,distance:cumulative};\n }\n const total=points.slice(1).reduce((n,p,i)=>n+distanceKm(points[i],p),0),airways=[...new Set(legs.filter(e=>e.kind===\'airway\').map(e=>e.airway))];\n let map=\'\';if(points.length>1&&points.every(validFix136)){\n  let last=points[0].lon;const geo=points.map(p=>{const lon=p.lon+360*Math.round((last-p.lon)/360);last=lon;return{...p,x:lon,y:-p.lat};}),xs=geo.map(p=>p.x),ys=geo.map(p=>p.y),x=Math.min(...xs),y=Math.min(...ys),width=Math.max(...xs)-x||.1,height=Math.max(...ys)-y||.1,pad=Math.max(width,height)*.08,unit=Math.max(width,height)/700;\n  map=`<svg class="route-overview184" viewBox="${x-pad} ${y-pad} ${width+2*pad} ${height+2*pad}" role="img" aria-label="Selected flight route with approach"><polyline points="${geo.map(p=>p.x+\',\'+p.y).join(\' \')}" fill="none" stroke="#c893f2" stroke-width="${unit*2}"/>${geo.filter(p=>!p.geometrySample145).map(p=>`<circle cx="${p.x}" cy="${p.y}" r="${unit*3}" fill="#71d3e6"><title>${esc(p.name)}</title></circle>`).join(\'\')}<text x="${geo[0].x}" y="${geo[0].y-unit*8}" fill="white" font-size="${unit*13}">${esc(departure.icao)}</text><text x="${geo.at(-1).x}" y="${geo.at(-1).y-unit*8}" fill="white" font-size="${unit*13}">${esc(arrival.icao)}</text></svg>`;\n }\n const runwayInfo=a=>`<article><h4>${esc(a.icao)} · ${esc(a.name)}</h4><p>Airport elevation: ${num(Number.isFinite(a.elevation)?a.elevation/.3048:undefined)} FT MSL</p><ul>${(a.runways||[]).map(r=>{const p={lat:r.a[1],lon:r.a[0]},q={lat:r.b[1],lon:r.b[0]};return `<li>RWY ${esc(r.name)} · ${num(distanceKm(p,q)*1000)} × ${num(r.width)} M · ${trackText(bearing(p,q))} / ${trackText(bearing(q,p))}</li>`;}).join(\'\')}</ul></article>`;\n return `<section class="route-brief184"><h3>Flight plan · ${esc(departure.icao)} → ${esc(arrival.icao)}</h3><div class="brief-metrics184"><div><small>AIRCRAFT</small><b>${esc(spec?.maker||\'\')} ${esc(spec?.name||\'Selected aircraft\')}</b></div><div><small>ROUTE DISTANCE</small><b>${points.length?num(total/1.852,1)+\' NM\':\'No sourced route\'}</b></div><div><small>WAYPOINTS</small><b>${rows.length}</b></div><div><small>LOCAL TIME</small><b>${localClock(w.localHour)}</b></div><div><small>WIND FROM</small><b>${num(w.windFromDeg)}°T / ${num(w.windSpeedKt)} KT${w.randomWindDirection156?\' · VARIABLE\':\'\'}</b></div><div><small>WEATHER</small><b>${num(w.visibility/1000,1)} KM VIS · ${num(w.cloudCover*100)}% CLOUD · ${num(w.rainMmHr,1)} MM/H</b></div></div><p><b>Airways:</b> ${esc(airways.join(\' / \')||\'No airway segment available\')} · <b>Data cycle:</b> ${esc(plan?.cycle||\'Not supplied\')}</p><p><b>Arrival:</b> ${esc(procedure?.procedure||\'No published arrival selected\')}${procedure?.runway?\' · RWY \'+esc(procedure.runway):\'\'}${procedure?.transition148?\' · Transition \'+esc(procedure.transition148):\'\'}</p>${map}<details open><summary>Route fixes & leg details · ${rows.length}</summary><div class="brief-table184"><table><thead><tr><th>#</th><th>FIX</th><th>VIA / SEGMENT</th><th>LEG NM</th><th>TRACK TRUE</th><th>TOTAL NM</th><th>ALTITUDE</th><th>SPEED</th><th>LAT / LON</th></tr></thead><tbody>${rows.join(\'\')}</tbody></table></div>${!rows.length?\'<p>\'+esc(plan?.reason||\'No sourced route available for this selection.\')+\'</p>\':\'\'}</details><details><summary>Published approach leg details · ${sourceRows.length}</summary><div class="brief-table184"><table><thead><tr><th>FIX</th><th>LEG TYPE</th><th>PHASE</th><th>ALTITUDE</th><th>SPEED</th><th>COURSE / TURN</th></tr></thead><tbody>${sourceRows.map(p=>`<tr><th scope="row">${esc(p.name)}</th><td>${esc(p.code||p.type||\'—\')}</td><td>${esc(p.phase||\'IAP\')}</td><td>${esc(altitudeText136(p))}</td><td>${esc(speedText136(p))}</td><td>${num(p.courseDeg??p.course)} ${esc(p.turn||\'\')}</td></tr>`).join(\'\')}</tbody></table></div>${link(procedure?.source)}<p>${esc(procedure?.note||\'Only available source legs are shown. Missing restrictions are not a clearance.\')}</p></details>${alternateAirports(arrival,airports)}<details><summary>Runway wind comparison</summary><p>${w.windSpeedKt===0?\'Calm wind.\':`Selected wind from ${num(w.windFromDeg)}°T at ${num(w.windSpeedKt)} kt.`} ${w.randomWindDirection156?\'Wind direction varies during flight. \':\'\'}Values exclude gusts.</p>${runwayWindTable(departure,w)}${runwayWindTable(arrival,w)}</details><details><summary>Departure & arrival runway information</summary><div class="airport-brief181">${runwayInfo(departure)}${runwayInfo(arrival)}</div></details><p class="modal-note">Tracks are true, not magnetic. Airway flight levels are segment limits, not fix crossing restrictions. Unpublished connections remain game guidance. Fuel, weight and ATC clearance are not calculated. ${link(plan?.source)}</p></section>`;\n}\n')
test_path = dist / 'tests/alternates201.test.mjs'
test_path.write_text("import assert from 'node:assert/strict';\nimport test from 'node:test';\nimport {routeBrief184} from '../src/route-brief184.js';\n\ntest('alternate list uses the destination, crosses the date line, excludes unavailable fields, and shows the longest runway', () => {\n const airport = (icao,lon) => ({icao,name:icao,lat:0,lon,runways:[{name:'09/27',a:[lon,0],b:[lon+.01,0],length:1113,width:30}]});\n const dest=airport('DEST',179.9), near=airport('NEAR',-179.9), far=airport('FAR',170);\n near.runways.push({...near.runways[0],name:'18/36',length:2050});\n const closed={...airport('EMPTY',179.95),runways:[]};\n const html=routeBrief184(far,dest,{airports:[dest,far,closed,near]});\n const section=html.split('<summary>Nearby alternate airports</summary>')[1].split('</details>')[0];\n assert.ok(section.indexOf('NEAR · NEAR') < section.indexOf('FAR · FAR'));\n assert.match(section,/NEAR · NEAR<\\/th><td>12 NM<\\/td><td>090°T<\\/td><td>18\\/36 · 2,050 M/);\n assert.doesNotMatch(section,/EMPTY|DEST · DEST/);\n});\n")
manifest['version'] = 201
release = json.dumps(manifest) + '\n'
manifest_path.write_text(release)
Path('data/render-release.json').write_text(release)
subprocess.run([sys.executable, 'scripts/version-runtime.py'], check=True)
subprocess.run(['node','--test','tests/alternates201.test.mjs','tests/runway-wind200.test.mjs'], cwd=dist, check=True)
changed = [app_path, brief_path, test_path, manifest_path]
names = {str(p.relative_to(dist)) for p in changed}
source = dist/'sources/game-source.zip'
tmp = source.with_suffix('.201.zip')
with zipfile.ZipFile(source) as old, zipfile.ZipFile(tmp,'w',compression=zipfile.ZIP_DEFLATED) as new:
    for item in old.infolist():
        if item.filename not in names:
            new.writestr(item, old.read(item.filename))
    for path in changed:
        new.write(path, str(path.relative_to(dist)))
tmp.replace(source)
